package com.proyecto.backus.controller;
import com.proyecto.backus.service.ProductosAdminService;
import org.springframework.stereotype.Controller;
import org.springframework.web.bind.annotation.*;
import org.springframework.ui.Model;
import org.springframework.validation.BindingResult;
import org.springframework.web.servlet.mvc.support.RedirectAttributes;
import jakarta.validation.Valid;
import java.security.Principal;
import com.proyecto.backus.service.ImagenProductoService;
import org.springframework.web.multipart.MultipartFile;
import com.proyecto.backus.service.GaleriaService;
import org.springframework.transaction.annotation.Transactional;
import java.util.List;
import java.util.ArrayList;
@Controller @RequestMapping("/admin/productos")
public class ProductosAdminController {
 private final ProductosAdminService service; private final ImagenProductoService imagenes; private final GaleriaService galeria;
 public ProductosAdminController(ProductosAdminService service,ImagenProductoService imagenes,GaleriaService galeria){this.service=service;this.imagenes=imagenes;this.galeria=galeria;}
 @ModelAttribute public void contexto(Model m,Principal p){m.addAttribute("adminCorreo",p.getName());m.addAttribute("adminPagina","productos");m.addAttribute("adminTitulo","Productos y presentaciones");}
 @GetMapping public String listar(Model m){var filas=service.listar();m.addAttribute("filas",filas);m.addAttribute("categorias",filas.stream().map(f->f.producto().getCategoria()).distinct().sorted().toList());return "admin/productos";}
 @GetMapping("/nuevo") public String nuevo(Model m){m.addAttribute("form",new ProductoAdminForm());m.addAttribute("productoId",null);return "admin/producto-form";}
 @GetMapping("/{id}/editar") public String editar(@PathVariable("id") Long id,Model m){var p=service.producto(id);var f=new ProductoAdminForm();f.setNombre(p.getNombre());f.setImagenUrl(p.getImagenUrl());f.setMarca(p.getMarca());f.setCategoria(p.getCategoria());f.setActivo(p.isActivo());m.addAttribute("form",f);m.addAttribute("productoId",id);m.addAttribute("fotos",galeria.listar(false,id,p.getImagenUrl()));return "admin/producto-form";}
 @Transactional
 @PostMapping({"/nuevo","/{id}/editar"}) public String guardar(@PathVariable(value="id",required=false) Long id,@Valid @ModelAttribute("form") ProductoAdminForm f,BindingResult errors,@RequestParam(value="imagenArchivo",required=false)MultipartFile archivo,@RequestParam(value="fotosArchivos",required=false)List<MultipartFile> archivos,@RequestParam(value="fotosEnlaces",defaultValue="")String enlaces,@RequestParam(value="quitarFotos",required=false)List<Long> quitar,@RequestParam(value="fotoPrincipal",defaultValue="")String principal,Model m,RedirectAttributes flash){m.addAttribute("productoId",id);m.addAttribute("fotos",galeria.listar(false,id,f.getImagenUrl()));if(errors.hasErrors())return "admin/producto-form";if(archivo!=null&&!archivo.isEmpty()){try{f.setImagenUrl(imagenes.guardar(archivo));}catch(IllegalArgumentException ex){errors.rejectValue("imagenUrl","imagen",ex.getMessage());return "admin/producto-form";}}try{var nuevas=prepararFotos(archivos,enlaces);String portada=validarGaleria(false,id,f.getImagenUrl(),nuevas,quitar,principal);var producto=service.guardarProducto(id,f);producto.setImagenUrl(galeria.guardar(false,producto.getId(),f.getImagenUrl(),nuevas,quitar==null?List.of():quitar,portada));}catch(IllegalArgumentException ex){errors.rejectValue("imagenUrl","galeria",ex.getMessage());return "admin/producto-form";}flash.addFlashAttribute("mensaje","Producto guardado correctamente.");return "redirect:/admin/productos";}
 @GetMapping("/{id}/presentaciones/nueva") public String nuevaPresentacion(@PathVariable("id")Long id,Model m){m.addAttribute("producto",service.producto(id));m.addAttribute("form",new PresentacionAdminForm());m.addAttribute("presentacionId",null);return "admin/presentacion-form";}
 @GetMapping("/{id}/presentaciones/{prId}/editar") public String editarPresentacion(@PathVariable("id")Long id,@PathVariable("prId")Long prId,Model m){var pr=service.presentacion(id,prId);var f=new PresentacionAdminForm();f.setDescripcion(pr.getDescripcion());f.setContenidoMl(pr.getContenidoMl());f.setUnidadesPorPaquete(pr.getUnidadesPorPaquete());f.setPrecio(pr.getPrecio());f.setImagenUrl(pr.getImagenUrl());f.setActivo(pr.isActivo());m.addAttribute("producto",service.producto(id));m.addAttribute("form",f);m.addAttribute("presentacionId",prId);m.addAttribute("fotos",galeria.listar(true,prId,pr.getImagenUrl()));return "admin/presentacion-form";}
 @Transactional
 @PostMapping({"/{id}/presentaciones/nueva","/{id}/presentaciones/{prId}/editar"}) public String guardarPresentacion(@PathVariable("id")Long id,@PathVariable(value="prId",required=false)Long prId,@Valid @ModelAttribute("form")PresentacionAdminForm f,BindingResult errors,@RequestParam(value="imagenArchivo",required=false)MultipartFile archivo,@RequestParam(value="fotosArchivos",required=false)List<MultipartFile> archivos,@RequestParam(value="fotosEnlaces",defaultValue="")String enlaces,@RequestParam(value="quitarFotos",required=false)List<Long> quitar,@RequestParam(value="fotoPrincipal",defaultValue="")String principal,Model m,RedirectAttributes flash){m.addAttribute("producto",service.producto(id));m.addAttribute("presentacionId",prId);m.addAttribute("fotos",galeria.listar(true,prId,f.getImagenUrl()));if(errors.hasErrors())return "admin/presentacion-form";if(archivo!=null&&!archivo.isEmpty()){try{f.setImagenUrl(imagenes.guardar(archivo));}catch(IllegalArgumentException ex){errors.rejectValue("imagenUrl","imagen",ex.getMessage());return "admin/presentacion-form";}}try{var nuevas=prepararFotos(archivos,enlaces);String portada=validarGaleria(true,prId,f.getImagenUrl(),nuevas,quitar,principal);var formato=service.guardarPresentacion(id,prId,f);formato.setImagenUrl(galeria.guardar(true,formato.getId(),f.getImagenUrl(),nuevas,quitar==null?List.of():quitar,portada));}catch(IllegalArgumentException ex){errors.rejectValue("imagenUrl","galeria",ex.getMessage());return "admin/presentacion-form";}flash.addFlashAttribute("mensaje","Presentación guardada correctamente.");return "redirect:/admin/productos";}
 private List<String> prepararFotos(List<MultipartFile> archivos,String enlaces){var urls=new ArrayList<>(galeria.enlaces(enlaces));var files=archivos==null?List.<MultipartFile>of():archivos.stream().filter(f->!f.isEmpty()).toList();for(var file:files)urls.add(imagenes.guardar(file));return urls;}
 private String validarGaleria(boolean pr,Long id,String actual,List<String> nuevas,List<Long> quitar,String principal){var lista=galeria.listar(pr,id,actual);var borradas=quitar==null?List.<Long>of():quitar;var ids=lista.stream().map(GaleriaService.Foto::id).toList();if(!ids.containsAll(borradas))throw new IllegalArgumentException("Foto no válida para esta galería.");var urls=new java.util.LinkedHashSet<String>();lista.stream().filter(f->!borradas.contains(f.id())).forEach(f->urls.add(f.url()));urls.addAll(nuevas);if(!principal.isBlank()&&!urls.contains(principal))throw new IllegalArgumentException("La foto principal está marcada para quitar. Selecciona otra.");return principal;}
}